// public/push-sw.js
// Web Push handlers for the app's generated service worker (story 063).
//
// The service worker itself (precache manifest, SPA navigation fallback and its
// deny list) is generated by vite-plugin-pwa; this file is pulled in with
// `workbox.importScripts` (see vite.config.js) so all of that reviewed behaviour
// stays generated config rather than hand-written code. It must live under
// `public/` because importScripts() resolves a served URL at activation time.
//
// Only three listeners are added: `push`, `notificationclick` and
// `pushsubscriptionchange`. Nothing here touches the precache or routing.

// Fallbacks so a malformed or absent payload still produces a visible
// notification instead of a silent drop (a push the user never sees is worse
// than a generic one).
const FALLBACK_TITLE = 'UFF English';
const FALLBACK_BODY = '';
const FALLBACK_URL = '/home';

function readPushPayload(event) {
    try {
        const data = event.data ? event.data.json() : null;
        if (!data || typeof data !== 'object') return null;
        return data;
    } catch (err) {
        // A non-JSON payload is not fatal: show the fallback copy.
        return null;
    }
}

// Same shape rule as the sender's collapse key (RFC 8030 §5.4): untrusted input
// gets dropped rather than passed to showNotification.
const TAG_PATTERN = /^[A-Za-z0-9_-]{1,32}$/;

function notificationTag(data) {
    const tag = data && typeof data.tag === 'string' ? data.tag.trim() : '';
    return TAG_PATTERN.test(tag) ? tag : undefined;
}

function notificationUrl(data) {
    const url = data && typeof data.url === 'string' ? data.url.trim() : '';
    if (!url) return FALLBACK_URL;
    // Only same-origin relative paths; a push is untrusted input.
    if (!url.startsWith('/') || url.startsWith('//')) return FALLBACK_URL;
    return url;
}

self.addEventListener('push', (event) => {
    const data = readPushPayload(event);
    const url = notificationUrl(data);
    const tag = notificationTag(data);
    const title = data && typeof data.title === 'string' && data.title ? data.title : FALLBACK_TITLE;
    const body = data && typeof data.body === 'string' ? data.body : FALLBACK_BODY;

    const options = {
        body,
        icon: '/pwa-192x192.png',
        badge: '/pwa-64x64.png',
        data: { url },
    };
    // A tag replaces the previous notification for the same key, so a repeated
    // answer updates one entry instead of stacking a column of them.
    if (tag) options.tag = tag;

    event.waitUntil(self.registration.showNotification(title, options));
});

self.addEventListener('notificationclick', (event) => {
    event.notification.close();
    const target = notificationUrl(event.notification.data);

    event.waitUntil(
        (async () => {
            const origin = self.location.origin;
            const targetUrl = new URL(target, origin).href;
            const clientList = await self.clients.matchAll({
                type: 'window',
                includeUncontrolled: true,
            });
            // Focus an existing window already showing the target path rather
            // than opening a second one.
            for (const client of clientList) {
                try {
                    if (new URL(client.url).pathname === new URL(targetUrl).pathname) {
                        return client.focus();
                    }
                } catch (err) {
                    // Unparseable client URL: skip it rather than abort the click.
                }
            }
            return self.clients.openWindow(targetUrl);
        })()
    );
});

// The browser replaced the subscription (typically a key rotation) while the app
// was closed. There is no session here, so the app re-registers the new
// endpoint itself: tell any open window, and every window reconciles on launch
// (see push-subscription-webonly.js). Nothing is sent from the worker.
self.addEventListener('pushsubscriptionchange', (event) => {
    event.waitUntil(
        (async () => {
            const clientList = await self.clients.matchAll({
                type: 'window',
                includeUncontrolled: true,
            });
            for (const client of clientList) {
                client.postMessage({ type: 'push-subscription-changed' });
            }
        })()
    );
});
